// Original drawings. The common soil-to-stem-tip scale is 2 SVG units per mm.
export function seedlingArt(row){
 const top=180-row.stemMm*2,spread=row.leafSpreadMm*2,colour=row.leafColour==='green'?'#398157':'#93b977';
 return `<svg class="ps-seedling" viewBox="0 0 140 220" role="img" aria-label="${row.conditionLabel}, seedling ${row.specimen}, day ${row.day}: ${row.description}"><rect x="26" y="20" width="100" height="160" rx="8" fill="#f2f7ed"/><path d="M32 180H126" stroke="#745b45" stroke-width="3"/><path d="M34 182H123L116 205H41Z" fill="#c78260"/><path d="M80 180V${top}" stroke="#4e7950" stroke-width="${row.stemWidthMm*2}"/><ellipse cx="${80-spread/4}" cy="${top+3}" rx="${spread/4}" ry="${spread/8}" fill="${colour}"/><ellipse cx="${80+spread/4}" cy="${top+3}" rx="${spread/4}" ry="${spread/8}" fill="${colour}"/><path d="M80 ${top+5}V${top}" stroke="#4e7950" stroke-width="${row.stemWidthMm*2}"/><path d="M26 40V180" stroke="#4b665b"/>${Array.from({length:8},(_,i)=>`<path d="M22 ${180-i*20}H30" stroke="#4b665b"/><text x="18" y="${183-i*20}" text-anchor="end" font-size="11" fill="#183f39">${i*10}</text>`).join('')}<text x="20" y="30" font-size="11" fill="#183f39">mm</text><text x="80" y="217" text-anchor="middle" font-size="11" fill="#183f39">${row.specimen} · ${row.stemMm} mm</text>${row.leafColour==='green'?'':'<text x="122" y="34" text-anchor="end" font-size="11" fill="#183f39">paler leaves</text>'}</svg>`;
}
